<template><AdminLayout title="Settings & X"><div class="admin-card"><h2>Site information</h2><div class="field"><label>Tagline</label><input v-model="settings.tagline"></div><div class="field"><label>WhatsApp number</label><input v-model="settings.whatsapp"></div><div class="field"><label>Official X username</label><input v-model="settings.x_username" placeholder="AkaoGloriah"></div><button class="btn btn-primary" @click="saveSettings">Save settings</button></div><div class="admin-card"><h2>X integration</h2><p>Official profile: <a href="https://x.com/AkaoGloriah" target="_blank" rel="noreferrer">@AkaoGloriah</a>. Automatic post syncing requires <code>X_USERNAME</code> and <code>X_BEARER_TOKEN</code> in the server environment. Tokens must stay on the server and cannot be entered into the browser.</p><button class="btn btn-primary" @click="sync" :disabled="syncing">{{syncing?'Syncing…':'Sync X now →'}}</button><p v-if="message" class="notice">{{message}}</p></div><div class="admin-card"><h2>Payment instructions</h2><p>These are editable so the run team can correct or update banking/mobile-money information without changing code.</p><div v-for="p in payments" :key="p.id" class="time-card" style="margin:12px 0"><h3>{{p.label}}</h3><div v-for="(v,k) in p.details" :key="k" class="field"><label>{{k}}</label><input v-model="p.details[k]"></div><label><input type="checkbox" v-model="p.is_active"> Active</label><br><button class="btn btn-primary" @click="savePayment(p)">Save {{p.label}}</button></div></div></AdminLayout></template>
<script setup>import {ref,onMounted} from 'vue';import axios from 'axios';import AdminLayout from '../components/AdminLayout.vue';const settings=ref({}),payments=ref([]),message=ref(''),syncing=ref(false);const load=async()=>{settings.value=(await axios.get('/api/admin/settings')).data;payments.value=(await axios.get('/api/admin/payments')).data};const saveSettings=async()=>{await axios.put('/api/admin/settings',{settings:settings.value});message.value='Settings saved.'};const savePayment=async p=>{await axios.put('/api/admin/payments/'+p.id,{label:p.label,details:p.details,sort_order:p.sort_order,is_active:p.is_active});message.value='Payment details saved.'};const sync=async()=>{syncing.value=true;try{message.value=(await axios.post('/api/admin/x/sync')).data.message}catch(e){message.value=e.response?.data?.message||'X sync failed.'}finally{syncing.value=false}};onMounted(load)</script>
